#!/usr/bin/env python3
"""Partitions every prop Caliper does not list (work/spectrum.universe.json, written by the oracle copy) by cause.
Usage: classify.py > classify.out.txt"""
import collections
import json
import os
import re

HERE = '/Users/gabe/Projects/caliper-fixtures/spectrum-gap'
ROOT = '/Users/gabe/Projects/caliper-fixtures/corpora/repos/react-spectrum'
u = json.load(open(HERE + '/work/spectrum.universe.json'))
cal = json.load(open(HERE + '/work/spectrum.caliper.json'))
reported_files = collections.defaultdict(list)
for c in cal['components'].values():
    reported_files[os.path.relpath(os.path.realpath(c['filePath']), os.path.realpath(ROOT))].append(c['displayName'])

comps = collections.defaultdict(list)
for e in u:
    comps[e['component']].append(e)


def source_line(file, name):
    try:
        text = open(os.path.join(ROOT, file), errors='replace').read()
    except OSError:
        return ''
    m = re.search(rf'^(?:export\s+)?(?:default\s+)?(?:async\s+)?(?:function\s+{re.escape(name)}\b[^\n]*|(?:const|let)\s+{re.escape(name)}\b[^\n]*)', text, re.M)
    return m.group(0)[:110] if m else ''


def cause(c, es):
    file, name = c.split('\0')
    stratum = {e['stratum'] for e in es}
    rdt_found = any(e['rdt'] not in ('component', 'failed_file') for e in es)
    if name == 'default':
        if file in reported_files:
            return 'N1 oracle names the default export `default`; Caliper reports it under its own name'
        return 'N2 default export Caliper does not report (leading underscore: `_3D`)'
    if re.match(r'use[A-Z0-9]', name):
        return 'H hook (use*): not a component (incl. lib-parameter hooks)'
    if name[:1].islower():
        return 'F lowercase function (style macro, helper, lib-parameter helper): not a component'
    line = source_line(file, name)
    if 'lazy(' in line or 'React.lazy' in line:
        return 'R1 React.lazy wrapper (documented gap, docs/edge-cases.md)'
    if re.search(r'\(\{[^}]*\}\)', line) and ':' not in line.split(')')[0]:
        return 'R2 PascalCase function with an unannotated destructured parameter (SKIPPED_CANDIDATE, deliberate)'
    return 'R3 other PascalCase: ' + line


tab = collections.defaultdict(lambda: collections.Counter())
members = collections.defaultdict(list)
for c, es in comps.items():
    for e in es:
        if e['caliper'] in ('component',):
            k = cause(c, es)
            tab[k][e['stratum']] += 1
            tab[k]['total'] += 1
            tab[k]['rdt_lists'] += e['rdt'] == 'listed'
            if c not in members[k]:
                members[k].append(c)
prop_level = [e for e in u if e['caliper'] == 'prop']
print('Props Caliper does not list, by cause (stratum split; rdt_lists = props RDT lists):')
total = 0
for k in sorted(tab):
    t = tab[k]
    total += t['total']
    print(f"{t['total']:5d}  {k}\n       strata: " + ', '.join(f'{s}={t[s]}' for s in ('same_file', 'other_project_file', 'dependency', 'unknown') if t[s])
          + f"; RDT lists {t['rdt_lists']}; components {len(members[k])}")
print(f'{len(prop_level):5d}  P component reported, prop omitted (stratum unknown)')
print('sum', total + len(prop_level))
print()
for k in sorted(tab):
    if k[:2] in ('R1', 'R2', 'R3', 'N2', 'F ', 'H '):
        print(k)
        for c in members[k][:60]:
            f, n = c.split('\0')
            print('    ', f.replace('packages/', '', 1), '::', n, len(comps[c]))
