import { API } from 'typescript-beta/sync'

const root = '/Users/gabe/Projects/caliper-fixtures/oracle-universe-scratch/probe'
const api = new API({ cwd: root })
const { options } = api.parseConfigFile(root + '/tsconfig.json')
const files = ['Badge.tsx', 'Arrow.tsx', 'Anon.tsx'].map((f) => `${root}/src/${f}`)
const program = api.createProgram(files, options)
const { checker } = program.getProject()
for (const file of files) {
  const mod = checker.getSymbolOfSourceFile(file)
  for (const ex of checker.getExportsOfModule(mod)) {
    const d = ex.declarations?.[0]
    let node: any
    try {
      node = d.resolve()
    } catch (e) {
      console.log('resolve failed', String(e))
    }
    console.log(
      file.split('/').pop(),
      'node',
      node && {
        keys: Object.keys(node),
        proto: Object.getOwnPropertyNames(Object.getPrototypeOf(node)),
        kind: node.kind,
        pos: node.pos,
        end: node.end,
        name: node.name && { kind: node.name.kind, text: node.name.text, pos: node.name.pos, end: node.name.end },
      },
    )
    let ownerFile: any
    try {
      ownerFile = d.fetchOwnerFile()
    } catch (e) {
      console.log('owner failed', String(e))
    }
    console.log(
      'owner',
      ownerFile && {
        keys: Object.keys(ownerFile),
        proto: Object.getOwnPropertyNames(Object.getPrototypeOf(ownerFile)),
        text: String(ownerFile.text).slice(0, 40),
      },
    )
  }
}
program.dispose()
api.close()

