import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { it } from 'vitest'
import { nonComponentReason, type ShapeProp } from '../src/component-shape.ts'

it('prints', () => {
  const fixture = JSON.parse(readFileSync(join(import.meta.dirname, 'fixtures', 'spectrum-universe-2026-11-09.json'), 'utf8'))
  const tally: Record<string, number[]> = {}
  let keep = [0, 0, 0]
  for (const [name, file, props, caliper, rdt, lib] of fixture.rows) {
    const declared = new Map<string, ShapeProp>(
      Array.from({ length: props }, (_, i) => [`p${i}`, { path: i < lib ? '/node_modules/typescript/lib/lib.dom.d.ts' : '/r/a.ts', type: () => 'string' }]),
    )
    const reason = nonComponentReason(name, `/r/${file}`, declared) ?? 'kept'
    const t = (tally[reason] ??= [0, 0, 0, 0])
    t[0]++
    t[1] += props
    t[2] += caliper
    t[3] += rdt
    if (reason === 'kept' && name !== 'default') keep = [keep[0] + props, keep[1] + caliper, keep[2] + rdt]
  }
  console.log(JSON.stringify(tally), keep)
})

